INSERT INTO `daily_reports` (`id`, `user_id`, `report_date`, `time_range`, `system_name`, `task_detail`, `work_result`, `remark`, `created_at`) VALUES
	(4, 1, '2026-01-17', '08:00-17:00', 'ระบบตาชั่งเล็ก', 'แก้ไข รายงานดึงข้อมูลรายการชั่งไม้ท่อนตัดน้ำหนัก\r\nเพิ่มประเภทการตัดน้ำหนัก ชั่งซื้อคืน ,ชั่งส่งคืน Update ทุกสาขา', 'เสร็จแล้ว', '', '2026-01-17 08:58:13'),
	(5, 1, '2026-01-17', '', 'ระบบ QR-Code', 'แก้ไขรายการชั่งซื้อไม้ท่อน ให้เวลาชั่ง ตรงตามเวลาชั่งจริง สาขา WT', 'เสร็จแล้ว', '', '2026-01-17 09:00:21'),
	(6, 1, '2026-01-17', '', 'ระบบ QR-Code', 'แก้ไขข้อผิดพลาดเบื้องต้น รายงานใบควบคุมสินค้าส่งออก แสดงข้อมูล ตู้ผิด\r\nเกิดจาก มีการแก้ไขข้อมูลระบบ AX ทำให้ข้อมูลไม่เชื่อมโยงกัน สาขา WA', 'เสร็จแล้ว', '', '2026-01-17 09:04:04'),
	(7, 1, '2026-01-17', '', 'ระบบค่าแรง4', 'เคลียร์ข้อมูล Qr-code นับไม้เปียกซ้ำ ออกจากระบบ สาขา WN', 'เสร็จแล้ว', '', '2026-01-17 09:08:35'),
	(8, 1, '2026-01-17', '', 'ระบบ QR-Code', 'แก้ไข รายงานการจัดซื้อวัตถุดิบ แยกตามประเภทการตัดน้ำหนัก\r\nเพิ่มข้อมูล ตัดไม้หนักไม้เสีย จากการประเมินไม้ท่อน Update ทุกโรงงาน', 'เสร็จแล้ว', '', '2026-01-17 09:35:31'),
	(9, 1, '2026-01-17', '', 'ระบบ QR-Code', 'แก้ไขข้อมูลรายการไม้ตัดหัว เคลียร์ข้อมูลคีย์ซ้ำออก 1 รายการ สาขา WU', 'เสร็จแล้ว', '', '2026-01-17 09:42:15'),
	(11, 12, '2026-01-17', '08:00-17:00', 'Hardware/Device', 'test', 'เสร็จแล้ว', '', '2026-01-17 09:49:57'),
	(12, 1, '2026-01-19', '08:00-17:00', 'ระบบ QR-Code', 'แก้ไขรายการชั่งซื้อไม้ท่อน ให้เวลาชั่ง ตรงตามเวลาชั่งจริง สาขา WT,WO', 'เสร็จแล้ว', '', '2026-01-19 09:51:51'),
	(13, 1, '2026-01-19', '', 'ระบบ QR-Code', 'แก้ไขข้อมูลรายการไม้ตัดหัว เคลียร์ข้อมูลคีย์ซ้ำออก 1 รายการ สาขา WU', 'เสร็จแล้ว', '', '2026-01-19 09:52:20'),
	(15, 1, '2026-01-19', '', 'ระบบ QR-Code', 'แก้ไขรายการส่งออก ปรับสถานะ ให้สามารถแก้ไขข้อมูลได้ใหม่\r\nเนื่องจากสถานะ Interface เข้าสู่ระบบ AX ไปแล้ว', 'เสร็จแล้ว', '', '2026-01-19 09:55:15'),
	(16, 1, '2026-01-19', '', 'ระบบ QR-Code', 'ทดสอบการทำรายการเรียงไม้แห่ง ขั้นตอนจัดกลุ่มเตาอบ มีข้อผิดพลาด \r\nบันทึก จัดกลุ่มเตาอบ ข้อมูลไม่ครบ และแสดงข้อมูลไม่ถูกต้อง', 'เสร็จแล้ว', 'กำลังส่งแก้ไข', '2026-01-19 09:58:27'),
	(17, 1, '2026-01-19', '', 'ระบบ QR-Code', 'รายการส่งออก ปรับสถานะ ให้ถูกต้อง เนื่องจากข้อมูลโอนแล้ว แต่สถานะไม่เปลี่ยนให้', 'เสร็จแล้ว', '', '2026-01-19 10:00:06'),
	(18, 1, '2026-01-19', '', 'ระบบบัญชี AX/ERP', 'แนบเอกสารรับ-จ่าย ตามรายการแจ้งของสาขา', 'เสร็จแล้ว', '', '2026-01-19 10:01:14'),
	(19, 1, '2026-01-19', '', 'ระบบบัญชี AX/ERP', 'เคลียร์เลขรันซ้ำ รายการ PO ไม้ท่อน เนื่องจากไม่สามารถโอนข้อมูลได้ สาขา WA', 'เสร็จแล้ว', '', '2026-01-19 10:01:47'),
	(20, 1, '2026-01-19', '', 'ระบบ Truck83', 'แก้ไขรายการชั่ง เนื่องจากคีย์ข้อมูลผิด ใช้สิทธิ Admin แก้ไข ตามรายการขออนุมัติ', 'เสร็จแล้ว', '', '2026-01-19 10:04:32'),
	(21, 1, '2026-01-20', '08:00-17:00', 'ระบบ QR-Code', 'แก้ไขข้อมูลนับไม้แห้ง เปลี่ยนพนักงานจัดเรียง เนื่องจากคีย์ผิด สาขา WU', 'เสร็จแล้ว', '', '2026-01-20 09:59:47'),
	(22, 1, '2026-01-20', '', 'ระบบ QR-Code', 'ตรวจสอบข้อมูลแพ็คกิ้ง ติดปัญหาจำนวนพาเลท ไม่ตรงกับรายงาน\r\nเกิดจากมีพาเลทที่คีย์ข้อมูลแพ็ทกิ้ง แต่ไม่มีข้อมูลนับไม้', 'เสร็จแล้ว', '', '2026-01-20 10:00:58'),
	(23, 1, '2026-01-20', '', 'ระบบ QR-Code', 'แก้ไขรายการชั่งซื้อไม้ท่อน ให้เวลาชั่ง ตรงตามเวลาชั่งจริง สาขา WT', 'เสร็จแล้ว', '', '2026-01-20 10:01:35'),
	(24, 1, '2026-01-20', '', 'ระบบ QR-Code', 'แก้ไขรายการชั่งซื้อไม้ท่อน ให้บัตรชั่ง สามารถปริ้นใหม่ได้อีกครั้ง\r\nตามรายการขออนุมัติ', 'เสร็จแล้ว', '', '2026-01-20 10:02:58'),
	(25, 1, '2026-01-20', '', 'ระบบ QR-Code', 'ส่งแก้ไขเมนูนับไม้แห้ง ขั้นตอนจัดกลุ่มเตาอบ เกิดข้อผิดพลาด\r\nจากข้อมูล หมายเลขเตาอบเดียวกัน อบไม้ 2 รอบ จัดกลุ่มเตาอบเดียวกัน', 'เสร็จแล้ว', '', '2026-01-20 10:04:42'),
	(26, 1, '2026-01-20', '', 'ระบบตาชั่งเล็ก', 'แก้ไขรายการชั่งซื้อไม้คืน เปลี่ยนรายการตัดน้ำหนัก เนื่องจากวางบิลไปแล้ว', 'เสร็จแล้ว', '', '2026-01-20 10:05:40'),
	(27, 1, '2026-01-20', '', 'ระบบ Truck83', 'แก้ไขรหัสเจ้าหนี้ โดยใช้สิทธิ Admin ตามรายการขออนุมัติ', 'เสร็จแล้ว', '', '2026-01-20 10:06:52'),
	(28, 1, '2026-01-20', '', 'ระบบค่าแรง4', 'ส่งแก้ไขปรับรูปแบบรายงาน ให้แสดงข้อมูลให้ครบถ้วน', 'กำลังดำเนินการ', '', '2026-01-20 10:07:37');
