INSERT INTO `issues` (`id`, `title`, `description`, `type_id`, `user_id`, `image_path`, `file_path`, `created_at`) VALUES
	(1, 'ข้อผิดพลาดปรับรายการใบสั่งผลิตไม้เลื่อย', 'ปัญหาข้อผิดพลาดการปรับรายการใบสั่งผลิต\r\nวิธีแก้ไข\r\n1. ระบบหลังบ้าน Table : PmfProdCoBy ค้นหา ProdID รหัสรายการใบสั่งผลิต -> ตรวจสอบ CoByOtySerie ที่เป็น 0 ปรับเป็น 1\r\n2. ไปที่ WW/Production control/Common/Production orders/All production orders\r\n3. Production order -> Cost -> Overview -> ตรวจสอบข้อมูลที่ปรับรายการ เปลี่ยน Cost allocation เป็น None เพื่อให้ระบบคำนวณต้นทุนให้ใหม่\r\n4. ถ้า Cost allocated มากกว่า หรือ น้อยกว่า 100 % ต้องปรับให้เป็น 100 ถึงจะผ่านรายการได้\r\n', 3, 1, '1748231782_ax_260525.jpg', NULL, '2025-05-26 03:44:22'),
	(23, 'เคลียร์ Pending invoices', 'ไปที่ :: \r\n1. WW/Accounts payable/Common/Vendor invoices/Pending vendor invoices\r\n2. WW/Accounts payable/Inquiries/History/Invoice history and matching details', 3, 1, '1748256886_แก้ไขรายการBom_300425.png', NULL, '2025-05-26 04:39:00'),
	(24, 'ปรับรายการใบสั่งผลิต', 'ถ้าปรับรายการ Report as finished ต้องเปิดใบ Rount Card อ้างอิงด้วย', 3, 1, '1748317977_freepik__background__75727.png', NULL, '2025-05-26 06:13:23'),
	(25, 'Closing and adjustment', 'เช็คสถานะ Recal', 3, 1, '1748313720_issue_270525_1.png', NULL, '2025-05-27 02:42:00'),
	(26, 'Batch jobs', 'ตั้งค่า Post ทำรายการต่างๆ ในระบบ', 3, 1, '1748313944_issue_270525_2.png', NULL, '2025-05-27 02:45:44'),
	(28, 'รหัสผ่านระบบ AX', 'รหัสผ่านระบบ AX\r\nEWOC : 154463\r\n\r\nEWGB\r\n010325\r\n\r\nEFAFN\r\nf4tos8\r\n\r\nFFDESC\r\nc20f1e', 9, 1, '1748425805_messageImage_1748424489126.jpg', '', '2025-05-28 09:50:05'),
	(29, 'รหัส wifi WG', 'Woodwork Guest\r\npass:: happycorp', 4, 1, NULL, NULL, '2025-05-29 08:59:06'),
	(30, 'API GET ข้อมูลลงทะเบียนไม้เลื่อย จากระบบตาชั่งเล็ก', 'http://192.168.3.2/scaleapi/getapi3.php?scaledate=2025-05-29&code=101017&sawTime=13', 1, 1, NULL, NULL, '2025-05-30 04:43:23'),
	(31, 'แก้ไขปัญหาลงทะเบียนชุดเลื่อย นับไม้เลื่อย GET ของมีจากระบบตาชั่งเล็ก', 'ฐานข้อมูลตาชั่งเล็ก :: scaledata\r\nALTER TABLE wood_weight \r\nADD INDEX idx_docdate_depcode_sawtime_prod (docdate, depcode, saw_time_id, prod_type_id);', 1, 1, NULL, NULL, '2025-05-30 08:14:51'),
	(32, 'API ตาชั่งเล็ก GET ข้อมูล log_woodqc', 'http://192.168.8.2:8080/woodwork_barcode_2/logWoodQC/listLogWoodQCSmalleScale/?qc_date=26042025&guage_number=100', 8, 1, NULL, NULL, '2025-05-31 09:26:26'),
	(33, 'รหัสเข้า Mini Airplay เปิดเพลง', '977292', 4, 1, NULL, NULL, '2025-06-04 03:48:15'),
	(34, 'Map สิทธิเข้าใช้งาน', '', 1, 1, '1749110506_Screenshot 2568-06-05 at 14.10.35.png', NULL, '2025-06-05 08:01:46'),
	(35, 'คำนวณค่าขนส่ง', 'สูตรคำนวณค่าขนส่งไม้แปรรูปต่างประเทศ\r\nExcel\r\nค่าชิปปิ้ง ,ค่าอื่น :: รายการชิปปิ้ง => นำจำนวนเงิน * สัดส่วนปริมาตร ลบ. เมตร ( ปริมาตร ตามข้อมูล สาขา ,เกรดไม้ / ปริมาตรทั้งหมด )\r\nค่าขนส่ง :: ปกติจะแยกตามสาขาอยู่แล้ว แต่ถ้าใน 1 สาขา มีข้อมูล เกรดไม้ มากกว่า 1 เกรด ให้ => นำจำนวนเงิน * สัดส่วนตามเกรดไม้ ในสาขานั้นๆ', 3, 1, '1749435915_สูตรคำนวณค่าขนส่ง.xlsx', '1761385612_68fc9c8c6d689_คำนวณค่าขนส่ง.xlsx', '2025-06-09 02:25:15'),
	(36, 'คำนวณค่าขนส่ง', 'สูตรคำนวณค่าขนส่งไม้แปรรูปต่างประเทศ\r\nภาพ', 3, 1, '1749436259_คำนวณค่าขนส่ง.png', '1761385586_68fc9c727dc83_คำนวณค่าขนส่ง.xlsx', '2025-06-09 02:26:42'),
	(37, 'Interface ไม้แห้ง', 'กรณี Qr-code ข้อมูลต่ำกว่า 2408 ระบบจะยึดเป็นเดือน 2408 ทั้งหมด', 1, 1, NULL, NULL, '2025-06-10 04:52:51'),
	(38, 'Transfer ผิดวัน', 'กรณีไม้นำไปใช้แล้ว\r\nรับเข้า -> ข้อมูล อ้างอิงจากรายการที่ผิด ลงวันที่เหมือนกัน -> Marking รายการที่ผิด \r\nTransfer ไปยังต้นทาง -> ตรวจเช็คข้อมูล warehouse ,batch ,location -- กลับรายการ\r\n\r\nTransfer ใหม่ -> ลงวันที่ให้ถูกต้อง\r\nเบิกออก -> เหมืนอข้อมูลรับเข้า -> Marking', 3, 1, '1749612871_Tranfer ผิดวัน.xlsx', NULL, '2025-06-11 03:34:31'),
	(39, 'ราคาขายไม่ตรงกับบิล', 'ตัวอย่าง\r\nยอดรวม : 655\r\nถอด Vat : 42.85\r\nคงเหลือ : 612.15\r\nจำนวนสินค้า : 6 ชิ้น\r\nราคาต่อชิ้น (Unit price) : 612.15/6 = 102.025\r\n\r\nกรณีทศนิยม ไม่ตรงกับ บิล\r\nไปที่ Line details -> Price and discount -> Price unit = 100\r\nนำ ราคาต่อชิ้น (Unit price) * Price unit -> นำไปใส่ที่ Unit price ใน Line รายการสินค้า\r\nรายการที่แก้ไข :: OCSOD2506018', 3, 1, '1750151754_ราคาขายไม่ตรงกับบิล.png', NULL, '2025-06-17 09:15:54'),
	(40, 'รหัสผ่าน Server', 'Qr-code', 9, 1, '', '1751707194_SERVERQRC_OLD.pdf', '2025-06-18 01:14:16'),
	(45, 'ทดสอบระบบ', 'ทดสอบระบบ', 4, 2, NULL, NULL, '2025-06-21 05:58:53'),
	(46, 'สร้าง LOG mysql', '/*สร้าง LOG*/\r\nSET global general_log = 1;\r\nSET global log_output = \'table\';\r\n\r\n\r\n/*เคลียร์ LOG*/\r\n/*\r\nTRUNCATE mysql.general_log;\r\nTRUNCATE mysql.slow_log;\r\n*/\r\n\r\nSELECT * \r\nfrom mysql.general_log \r\n	WHERE thread_id <> 7 \r\norder by event_time desc', 5, 1, NULL, NULL, '2025-06-21 08:19:32'),
	(47, 'รัน Master planning {จัดซื้อ}', '', 3, 1, '1750918163_อัพเดท master plan จัดซื้อ.docx', NULL, '2025-06-26 06:09:23'),
	(48, 'ปัญหา Recal ค่าแรงนายม้าไม่ได้', 'เช็คข้อมูล log_woodqc.production_formular มีใน tb:wood_conversion_standard หรือไม่', 1, 1, '1750924875_26-6-2025 13-52-26.png', NULL, '2025-06-26 08:01:15'),
	(49, 'สูตรคำนวณบางส่วนค่าแรงนายม้า', '- เป้าหมาย AB (%)\r\n- เป้าหมายอัตราแลเนื้อ (ลบ.ฟ./ตัน)', 1, 1, '1750928686_26-6-2025 15-58-39.png', NULL, '2025-06-26 09:04:46'),
	(50, 'ปัญหา interface ใบสั่งผลิต PK', 'ปัญหา : ข้อมูล Qr-code นับไม้แห้ง ไม่มีข้อมูลอ้างอิงที่มา\r\nเช็ครายงาน Metabase\r\n9.4 รายงานที่มาไม้แห้ง ตามการอ้างอิงตัดไม้ (ตามคิวอาร์โค้ด) -> เช็คส่วนต่าง', 1, 1, '1751332670_interface_pk.jpg', '1751946299_686c943be4e6e_เบอร์โทรศัพท์ภายใน WG 02.04.2568.pdf', '2025-07-01 01:17:50'),
	(51, 'Update Qr-code ไม้แห้ง สถานะเป็นไม้จัดเรียง aa', 'SELECT b.* FROM\r\n-- update \r\nbarcode a\r\nLEFT JOIN mobile_dry_wood_data b ON b.barcode_id = a.id\r\n-- SET b.process_state = 0 ,b.time_dispense = null\r\nWHERE a.barcode_id IN (\r\n	\'wc290625st0336\',\r\n	\'wc180725st0064\'\r\n)', 5, 1, NULL, NULL, '2025-07-04 09:48:07'),
	(52, 'Update รายการส่งออก ให้ข้อมูล Qr-code เปิดใช้งาน', 'select * from\r\n-- update \r\nwood_export_exportitem\r\n-- set is_active = true\r\nwhere id in (\r\n	select a.id\r\n	from wood_export_exportitem a\r\n	left join public.wood_export_exportsaleline b on b.id = a.export_sale_line_id\r\n	left join public.wood_export_exporttransaction c on c.id = b.transaction_id\r\n	left join barcode_barcode d on d.id = a.barcode_id\r\n	where c.sale_order_no = \'Lsoe2507120\' and c.container_no = \'1\'\r\n)', 6, 1, NULL, NULL, '2025-07-04 09:51:15'),
	(53, 'ดึงข้อมูลรายการ Bom', 'select barc.barcode_no,barst.* \r\nfrom public.bom_bomtransaction bt\r\nleft join public.bom_bom bb on bb.transaction_id = bt.id\r\nleft join public.barcode_woodsizeamountmap bwa on bwa.id = bb.wood_size_amount_map_id\r\nleft join public.barcode_barcode barc on barc.id = bwa.barcode_id\r\nleft join public.barcode_woodstore barst on barst.id = bwa.wood_store_id\r\nwhere bt.order_no = \'ALSOD2507002\'', 6, 1, NULL, '1752032123_686de37be38a1_02-07-68.xlsx', '2025-07-08 01:52:25'),
	(57, 'ปัญหา รายงานการจ่ายโบนัส 2 สรุปภาพรวม ข้อมูลไม่ตรง', 'ปัญหา มีการแก้ไขข้อมูลรายการคัดแยกไม้ท่อน แต่ไม่ได้ทำรายการ Recal ข้อมูล\r\nวิธีแก้ไข :: ดำเนินการ Recal ข้อมูลตามลำดับ\r\n- รายงานค่าแรงนายม้า\r\n- รายงานรายละเอียดประจำวัน\r\n- รายงานโบนัส 2', 1, 1, '1752025793_686dcac121c67_จ่ายโบนัส 2.jpg', NULL, '2025-07-09 01:49:53'),
	(58, 'ค่าขนส่ง9', '- สร้างรายการค่าขนส่ง\r\n- ตั้งค่าเรทค่าขนส่ง\r\n- Update น้ำหนักปลายทาง - ปลายไม้\r\n- Deliver remainder ไม่รับน้ำหนักเพิ่ม', 3, 1, '1752054665_686e3b899ba66_ค่าขนส่ง.png', NULL, '2025-07-09 09:51:05'),
	(59, 'แก้ไขราคาซื้อไม้ โดยอ้างอิงจากสาขาที่กำหนดราคาแล้ว (Query)', '/*อ้างอิงจาก PDW-ว0022-04*/\r\nselect * \r\nfrom Suppliers_price a\r\ninner join Suppliers_price b on b.stkbarc1 = a.stkbarc1\r\nwhere a.crecode = \'PDW-ว0022-04\' and  b.crecode = \'PDW-ว0022-05\'\r\n\r\nupdate Suppliers_price a\r\ninner join Suppliers_price b \r\n	on b.stkbarc1 = a.stkbarc1\r\nset b.UnitPrice = a.UnitPrice\r\n	      ,b.UnitPrice1 = a.UnitPrice1\r\n      	,b.UnitPrice2 = a.UnitPrice2\r\nwhere a.crecode = \'PDW-ว0022-04\' \r\n	and b.crecode = \'PDW-ว0022-05\'', 7, 1, NULL, NULL, '2025-07-15 03:10:37'),
	(60, 'แก้ไขสถานะคำนวณค่าแรง ระบบตาชั่งเล็ก', 'SELECT a.*\r\nFROM \r\n-- update\r\nwood_weight a\r\nLEFT JOIN saw_time b ON b.id = a.saw_time_id\r\n-- SET a.wage_status = 0\r\nWHERE a.docdate = \'2025-07-11\' AND a.prod_type_id = 2\r\n	AND (depcode BETWEEN \'101007\' AND \'101020-99\' OR depcode BETWEEN \'101027\' AND \'101033-99\')\r\n	AND b.code = 11\r\n	AND a.wage_status = 1', 8, 1, NULL, NULL, '2025-07-16 06:34:14'),
	(61, 'เพิ่ม index ระบบตาชั่งเล็ก', 'แก้ไขปัญหาดึงข้อมูล ลงทะเบียนนายม้า ขั้นตอนยิง Qr-code นับไม้เลื่อย\r\n\r\nALTER TABLE wood_weight ADD INDEX `idx_docdate_depcode_sawtime_prod` (`docdate`, `depcode`, `saw_time_id`, `prod_type_id`);', 8, 1, NULL, NULL, '2025-07-17 09:20:54'),
	(62, 'อัพเดต config เครื่องทดสอบ', 'SET @url_createpo := \'/Purchtest/PurchaseOrderService.svc/createPurchOrder\';\r\nSET @url_dispense := \'/salestest/SalesJournalService.svc/createjournal\';\r\nSET @url_log_wood := \'/prodtest/ProdJournalService.svc/createProdLG\';\r\nSET @url_movement := \'/prodtest/ProdJournalService.svc/createProd121\';\r\nSET @urlsm := \'/prodtest/ProdJournalService.svc/createProdSM\';\r\nSET @url_slab_boiler := \'/inventTest/api/InventMovIssue.svc/create\';\r\nSET @url_transfer := \'/Transfertest/TransferjournalService.svc/createTransfer\';\r\nSET @url_bom := \'/inventtest/api/InventBom.svc/create\';\r\n\r\nUPDATE axconfiguration\r\nSET \r\n	url_createpo = @url_createpo\r\n	,url_dispense = @url_dispense\r\n	,url_log_wood = @url_log_wood\r\n	,url_movement = @url_movement\r\n	,urlsm = @urlsm\r\n	,url_slab_boiler = @url_slab_boiler\r\n	,url_transfer = @url_transfer\r\n	,urlbom = @url_bom\r\nLIMIT 1;\r\n	\r\nSET @interface_saw := \'http://192.168.0.18/scaleapi/getapi3.php?\';\r\nSET @interface_udpate := \'http://192.168.0.18/scaleapi/updatepiece.php\';\r\nSET @qr_code_new := \'http://wg.al8m.com/\';\r\n\r\nUPDATE web_configuration\r\nSET \r\n	interface_saw_worker_set_url = @interface_saw\r\n	,interface_udpate_piece_url = @interface_udpate\r\n	,qr_code_new_server_url = @qr_code_new\r\nLIMIT 1;', 5, 1, NULL, NULL, '2025-07-18 07:02:56'),
	(63, 'เพิ่มข้อมูลเกรด ABC', 'INSERT INTO wood_grade (VERSION,grade_code,grade_name) VALUES (1,4,\'ABC\')', 5, 1, NULL, NULL, '2025-07-23 03:33:41'),
	(64, 'ขั้นตอน Confirm PO ไม่สามารถปริ้นเอกสารได้', 'เคลียร์ Usage Data ทั้งหมด', 3, 1, '1753414712_6882fc388b23b_confirm_po_print.jpg', NULL, '2025-07-25 03:38:32'),
	(65, 'คำนวณน้ำหนักหลังทอน', 'กลุ่ม No.1\r\n1. น้ำหนักตามกลุ่มไม้ / จำนวนท่อนตามกลุ่มไม้ = น้ำหนักเฉลี่ยต่อท่อน\r\n2. ลบ. ฟุตตามความยาว / ลบ. ฟุตทั้งหมด (เปอร์เซ็นความยาวปริมาตร ลบ. ฟุต (ใช้ทุกกลุ่มไม้))\r\n3. (1*2)/100*ความยาว[90,100]\r\n4. รวมทุกความยาว จะได้น้ำหนักหลังทอน', 1, 1, '1753436888_688352d884e19_น้ำหนักหลังทอน.png', NULL, '2025-07-25 09:48:08'),
	(66, 'เพิ่ม-แก้ไข Warehouse Location สต๊อกสินค้า', 'เพิ่ม-แก้ไข Warehouse Location สต๊อกสินค้า', 3, 1, '1753774802_68887ad21f036_เพิ่มแก้ไขสโตร์.png', NULL, '2025-07-29 07:40:02'),
	(67, 'ติดปัญหา interface ไม้แห้ง PK', 'ข้อมูลไม่ตรงกันกับระบบ AX ไม่พบข้อมูล Location จากข้อมูล Json Interface\r\nImport. Execution id : 202507290024. Line number : 66.00. Posting - Report as finished journal. Journal: P251611212. Update has been canceled', 3, 1, '1753778796_68888a6c16777_messageImage_1753756241075.jpg', NULL, '2025-07-29 08:46:36'),
	(68, 'รายการส่งออก ฟอร์มพิมพ์ใบ Invoice เพี้ยน', 'ข้อมูลรายระเอียด โดน Enter ตอนทำรายการ ทำให้ฟอร์มพิมพ์ใบกำกับ เพี้ยนไปด้วย', 3, 1, '1753858751_6889c2bf36fc3_ฟอร์มInvoiceเพี้ยน.png', NULL, '2025-07-30 06:59:11'),
	(69, 'Interface LG ใหม่', 'SELECT log_woodqc.scale_date_time,log_woodqc.is_interfaced From \r\n-- update\r\nlog_woodqc \r\n-- set log_woodqc.is_interfaced = 0\r\nWhere DATE(log_woodqc.scale_date_time) = \'2025-07-10\' \r\n	and log_woodqc.is_interfaced = \'1\'', 5, 1, NULL, NULL, '2025-08-02 04:21:24'),
	(70, 'Interface SM ใหม่', '/*log_woodqc*/\r\nselect *\r\nFROM \r\n-- update\r\nlog_woodqc\r\n-- set is_interfacedsm = 0\r\nwhere scale_date_time =\'2025-07-10\'\r\n\r\n/*wood_size_amount_map*/\r\nselect w.*\r\nFROM \r\n-- update \r\nwood_size_amount_map w\r\ninner join mobile_raw_wood_data_wood_size_amount_map s on s.wood_size_amount_map_id = w.id\r\ninner join mobile_raw_wood_data d on d.id = s.mobile_raw_wood_data_amount_map_id\r\ninner join raw_wood_source r on r.id = d.raw_wood_source_id\r\ninner join barcode b on b.id = r.barcode_id\r\n-- set w.is_interfacedsm =0\r\nWHERE DATE(r.produce_date) =\'2025-07-10\'', 5, 1, NULL, NULL, '2025-08-02 04:26:00'),
	(71, 'ขั้นตอนเข้า เพิ่มสิทธิการใช้งาน', 'ขั้นตอนเข้า เพิ่มสิทธิการใช้งาน', 3, 1, '1754467806_68930dde4fc9b_เพิ่มสิทธิการใช้งาน.png', NULL, '2025-08-06 08:10:06'),
	(72, 'Query ดึงข้อมูลพนักงานจากระบบ Mas', 'SELECT\r\ndbo.tEmployee.EmployeeCode AS code\r\n,dbo.tEmployee.EnglishName AS name_en\r\n,dbo.tEmployee.FirstName + \' \' + dbo.tEmployee.LastName AS name\r\n,dbo.tEmployeeTitle.EmployeeTitle AS title\r\n,dbo.tEmployeeTitle.EmployeeTitle_EN AS title_en\r\n,dbo.tEmployeeStatus.EMPStatus AS status\r\n,dbo.tEmployeeStatus.EMPSTG_ID, dbo.tSiteTR.Site_Name\r\nFROM dbo.tEmployee\r\nINNER JOIN dbo.tEmployeeTitle ON dbo.tEmployee.EMPTT_ID = dbo.tEmployeeTitle.EMPTT_ID\r\nINNER JOIN dbo.tEmployeeStatus ON dbo.tEmployee.EMPST_ID = dbo.tEmployeeStatus.EMPST_ID\r\nINNER JOIN dbo.tSiteTR ON dbo.tEmployee.Site_ID = dbo.tSiteTR.Site_ID\r\nWHERE 1=1 \r\n	-- AND (dbo.tEmployee.EmployeeCode = \'2023-00339\')\r\n	AND dbo.tSiteTR.Site_Name = \'WG\'\r\n	AND dbo.tEmployeeStatus.EMPSTG_ID = \'AC\'', 4, 1, NULL, NULL, '2025-08-07 01:40:57'),
	(73, 'ปัญหาข้อมูลรหัสสินค้าผิด ไม้เปียก', 'กรณีโอนข้อมูล Transfer เข้าสู่ระบบ AX แล้ว\r\nให้แก้ไขข้อมูล ไม้เข้าเตา ใช้วิธีการ Bom เปลี่ยนไซต์ รหัสสินค้าให้ถูกต้อง', 3, 1, NULL, NULL, '2025-08-08 02:37:26'),
	(74, 'การรับใบแจ้งหนี้ (Invoice Receipt): หรือใบวางบิล', 'Bill Receipt -> Bill Process -> Bill receive date (วันที่รับ) -> ระบุรหัสเจ้าหนี้', 3, 1, '1754882311_689961073e78f_11-8-2025 9-52-34.png', NULL, '2025-08-11 03:18:31'),
	(75, 'ปัญหารายงานรายละเอียดประจำวันขึ้นข้อมูลแหล่งที่มา ไม่ตรงกับรายการชั่ง', 'เกิดจากการแก้ไขข้อมูลแหล่งที่มา จากระบบ QR-code ข้อมูลแหล่งที่มา ที่นำไปคำนวณไม่เปลี่ยนให้\r\nแก้ไขเบื้องต้น :: ให้เข้าไปแก้ไขรายการชั่ง ในระบบตาชั่งเล็ก รายการชั่งในชุดเลื่อยทั้งหมด แล้ว Recal ใหม่', 1, 1, '1755056430_689c092ee29b8_13-8-2025 10-34-36.png', NULL, '2025-08-13 03:40:30'),
	(76, 'Query เคลียร์ Process sleep แก้ไขปัญหาระบบช้า', '-- ตรวจสอบ process\r\nSELECT *\r\nFROM INFORMATION_SCHEMA.PROCESSLIST\r\n\r\n-- สร้าง kill commands\r\nSELECT CONCAT(\'KILL \', ID, \';\') as kill_command \r\nFROM INFORMATION_SCHEMA.PROCESSLIST \r\nWHERE COMMAND = \'Sleep\' \r\nAND TIME > 3600\r\nAND USER != \'root\';  -- ป้องกันไม่ให้ kill root connections', 5, 1, NULL, NULL, '2025-08-14 09:17:55'),
	(77, 'แก้ไขปัญหา รับไม้สาขา ผิด ถูกเบิกไปใช้ในใบสั่งผลิต CT แล้ว', 'ระบุวันที่ ตามรายการที่ผิด', 3, 1, '1755586834_68a421127a888_ax190825.png', NULL, '2025-08-19 07:00:34'),
	(78, 'ตาชั่งเล็ก ไม่สามารถบันทึกรายการชั่งไม้ท่อนได้', 'สาเหตุ :: ตามรายการแจ้งเตือน รหัสเจ้าหนี้ ยังไม่ได้เปิดใช้งาน ในระบบ Qr-code ทำให้ระบบ Qr-code ปฏิเสธ การบันทึก รหัสเจ้าหนี้\r\nแก้ไขโดย :: ตรวจสอบรหัสเจ้าหนี้จากระบบ Qr-Truck เปลี่ยนสถานะเป็น เปิดใช้งาน รหัสเจ้าหนี้ แล้วระบบจะ sync มาให้ระบบ Qr-code อัตโนมัติ', 8, 1, '1755664024_68a54e980b898_messageImage_1755662355952_new.jpg', NULL, '2025-08-20 04:27:04'),
	(79, 'ข้อผิดพลาด บันทึกรายการชั่ง ไม่ส่งไปบันทึกรายการตรวจรับไม้ท่อน', '1. ดึงรายการตรวจรับไม้ท่อน เกจ์ 001 เพื่อชั่งน้ำหนัก บันทึกสำเร็จ มีรหัส QC-ID แล้ว แต่ระบบไม่ส่งไปบันทึกในรายการตรวจรับไม้ท่อน ระบบ Qr-code\r\n2. ดึงรายการตรวจรับไม้ท่อน เกจ์ 001 มาอีกครั้ง ดึงได้ เพราะสถานะในระบบ Qr-code ยังไม่ได้ชั่ง แต่ไม่สามารถบันทึกรายการได้ เนื่องจากมีข้อมูล QC-ID ในระบบตาชั่งเล็กแล้ว\r\n\r\n-- Query-check\r\n\r\nSELECT * FROM scaledata.wood_weight a\r\ninner JOIN log_woodqc b ON b.id = a.qrcodegetid\r\nWHERE b.scale_date_time IS NULL AND DATE(a.docdate) > \'2025-08-24\'', 8, 1, '1756188882_68ad50d20ba14_ข้อผิดพลาดการชั่งปีกไม้.png', NULL, '2025-08-26 06:14:42'),
	(80, 'รหัสแท็บเล็ต เปิดเพลง', '126498', 4, 1, NULL, NULL, '2025-08-30 03:11:25'),
	(81, 'กลับรายการใบสั่งผลิตไม้เลื่อย', 'กรณี สร้างกลับรายการ ใบ Packinglis เบิกไม้ออก ต้อง เลือก ด้วย Lot ID\r\n\r\nใบ Planning -> Packinglist ปรับรายการเบิกออก ให้เลือกด้วย Lot ID ครับ', 3, 1, '1756697348_68b513043fb1f_1-9-2025 10-27-28.png', NULL, '2025-09-01 02:24:30'),
	(82, 'ปรับรายการ ยกเลิกใบสั่งผลิต PK ไม่ได้เปลี่ยน วันที่ system date', '- ยกเลิกใบสั่งผลิต ต้องเปลี่ยนวันที่ system date ให้ตรงกับ วันที่ผลิต', 3, 1, '1756801315_68b6a9232c007_2-9-2025 15-21-03.png', NULL, '2025-09-02 08:21:55'),
	(83, 'ทำรายการ ลดปริมาณค้างส่งของ SOD ของปีไม้', 'ติดรายการ picked ยังไม่ผ่านรายการ invoice จึงไม่สามารถ ลดปริมาณยอดที่ รวม picked ได้', 3, 1, '1757306728_68be5f6876c48_messageImage_1757305545157.jpg', NULL, '2025-09-08 04:45:28'),
	(84, 'ตั้งค่า Route รหัสสินค้า ไม้แห้ง', 'จากปัญหา ไม่สามารถเปิดใบสั่งผลิต PK ได้ เนื่องจาก รหัสสินค้า ไม่ได้ตั้ง Route ตามสาขา นั้นๆ', 3, 1, '1757385558_68bf93563ac76_ตั้งค่าชั่วโมงการทำงานPK.png', NULL, '2025-09-09 02:39:18'),
	(85, 'Query ชั่วคราว', 'SELECT \r\n	a.DELIVERYDATE,b.salesid,b.ITEMID,b.qtyordered,b.SALESQTY,b.salesunit,b.ECL_TOTALCONT,b.SALESSTATUS,c.inventsiteid \r\nFROM SALESTABLE a \r\nLEFT JOIN SALESLINE b ON b.SALESID = a.SALESID\r\nLEFT JOIN INVENTDIM c ON c.INVENTDIMID = b.INVENTDIMID\r\nWHERE CONVERT(DATE, a.DELIVERYDATE) BETWEEN \'2025-09-01\' AND \'2025-09-12\' \r\n	-- AND a.SALESID = \'LSOE2509016\'\r\n	-- AND b.SALESSTATUS = 3\r\n	AND b.ITEMID LIKE \'5%\'\r\nORDER BY a.DELIVERYDATE,b.salesid', 3, 1, NULL, NULL, '2025-09-17 09:55:33'),
	(86, 'DataImport Number sequences', 'ขั้นตอนการ Import ข้อมูลดูได้จากภาพ', 3, 1, '1758360731_68ce749ba1531_20-9-2025 16-19-49.png', '1758360731_68ce749ba17a5_NumberSequence_WGH420.csv', '2025-09-20 09:32:11'),
	(87, 'Update สถานะ ประเมินไม้ท่อน', 'SELECT c.* FROM public.log_wood_logwoodevaluationdata a\r\nleft join scale_large_trucktransaction b on b.id = a.truck_transaction_id\r\nleft join workflow_logwoodpoworkflow c on c.truck_transaction_id = b.id\r\nwhere b.ticket2 = \'0000206918\'\r\nORDER BY a.id desc LIMIT 100\r\n\r\nselect * from workflow_logwoodpoworkflow\r\n--update workflow_logwoodpoworkflow set state = \'wait_md_approve\'\r\nwhere id = \'209\'\r\n\r\n/* \r\nwait_md_approve\r\nwait_manager_approve\r\nend\r\n*/', 6, 1, NULL, NULL, '2025-10-06 03:36:19'),
	(90, 'โหลดต้นทุนไม้แปรรูปสด และ คำนวณต้นทุนไม้แปรรูปสด', 'กระบวนการคำนวณต้นทุนการเบิกไม้ท่อน (RMG) ตามกลุ่มเกรด\r\nกระบวนการคำนวณต้นทุนการเบิกไม้ท่อนจากคลังวัตถุดิบ (RMG) จะแบ่งตามกลุ่มเกรดของไม้ โดยมีวิธีการคำนวณที่แตกต่างกัน 2 รูปแบบดังนี้:\r\n\r\nกลุ่มที่ 1: ไม้เกรด C, P, และ PP (ต้นทุนคงที่ - Fixed Cost)\r\nสำหรับไม้กลุ่มนี้ จะใช้ต้นทุนคงที่ซึ่งกำหนดโดยฝ่ายบัญชีเป็นหลักในการคำนวณ\r\n\r\nกำหนดต้นทุน: ฝ่ายบัญชีจะเป็นผู้กำหนด ต้นทุนคงที่ (Fixed Cost) ต่อหน่วย (เช่น ต่อลูกบาศก์ฟุต) สำหรับไม้แต่ละเกรดในกลุ่มนี้\r\n\r\nนำเข้าข้อมูล: ต้นทุนดังกล่าวจะถูกนำเข้าระบบผ่าน Template Excel Add-in\r\n\r\nการคำนวณ: เมื่อมีการเบิกไม้ในกลุ่มนี้ ระบบจะคำนวณต้นทุนโดยใช้สูตร:\r\nต้นทุนรวมของไม้กลุ่มนี้ = ปริมาตรไม้ที่เบิก (ลบ. ฟุต) x ต้นทุนคงที่ต่อหน่วย\r\n\r\nกลุ่มที่ 2: ไม้เกรด AB (ต้นทุนเฉลี่ย - Average Cost)\r\nสำหรับไม้เกรด AB จะใช้วิธีคำนวณต้นทุนเฉลี่ย ซึ่งเป็นต้นทุนที่เหลือหลังจากหักต้นทุนของไม้กลุ่มแรกออกไปแล้ว\r\n\r\nคำนวณต้นทุนคงค้าง: ระบบจะนำ ต้นทุนรวมของการเบิกไม้ RMG ทั้งหมด มาหักลบด้วย ต้นทุนรวมของไม้เกรด C, P, PP ที่คำนวณได้จากกลุ่มที่ 1\r\nต้นทุนรวมเกรด AB = ต้นทุนเบิก RMG ทั้งหมด - ต้นทุนรวม (C, P, PP)\r\n\r\nหาต้นทุนเฉลี่ย: นำต้นทุนรวมของไม้เกรด AB ที่ได้จากขั้นตอนแรก มาคำนวณหาต้นทุนเฉลี่ยต่อหน่วย\r\nต้นทุนเฉลี่ยเกรด AB = ต้นทุนรวมเกรด AB / ปริมาตรไม้เกรด AB ทั้งหมดที่เบิก (ลบ. ฟุต)\r\n\r\nบันทึกต้นทุน: ระบบจะนำ ต้นทุนเฉลี่ย ที่คำนวณได้ ไปบันทึกเป็นต้นทุนให้กับไม้เกรด AB แต่ละรหัสสินค้าที่ถูกเบิกไปในครั้งนั้นๆ', 3, 1, NULL, '1760070540_68e88b8ca2c68_คำนวณต้นทุนไม้แปรรูปสด.xlsx', '2025-10-10 04:29:00'),
	(91, 'รายการ PO ทั่วไป กด submit ไม่ได้', 'แก้ไขเข้าไปที่ Line รายการสินค้า -> Financials -> Distribute amounts -> Reset\r\n\r\nThis action can only be completed after the line number 10 is fully distributed', 3, 1, '1760433529_68ee1579f1918_messageImage_1760432346496.jpg', '1760433529_68ee1579f1b4f_messageImage_1760433252710.jpg', '2025-10-14 09:18:49'),
	(92, 'ติดปัญหา End ใบสังผลิตไม้เลื่อย', 'ต้นทุนไม่เฉลี่ยให้ วิธีแก้ไขตามภาพที่แนบ', 3, 1, '1760497689_68ef10194a19f_ติดปัญหา End ต้นทุนไม่เฉลี่ยให้.png', NULL, '2025-10-15 03:08:09'),
	(93, 'Query ดึงข้อมูล รหัสเจ้าหนี้ และ ข้อมูล VatBranch', 'SELECT \r\n	T1.ACCOUNTNUM,T1.ECL_PAYEENAME,T2.name,T3.VATBRANCHID\r\nfrom VENDTABLE T1\r\nLEFT JOIN DIRPARTYTABLE T2 on T1.PARTY=T2.RECID\r\nLEFT JOIN ECL_CUSTVENDVATBRANCH T3 ON T3.CUSTVENDACCOUNT = T1.ACCOUNTNUM\r\nWHERE T1.ACCOUNTNUM = \'PTR-23095-00\'', 3, 1, NULL, NULL, '2025-10-15 07:02:06'),
	(94, 'test', 'test', 1, 5, NULL, NULL, '2025-10-17 06:43:24'),
	(95, 'Query ลบข้อมูล Qr-code ระบบค่าแรง 4 (dbwood)', 'select * from sub \r\nwhere docno in (\r\n	SELECT docno from main where docdate between #2020-01-01# and #2020-12-31#\r\n)\r\n\r\nSELECT * from main where docdate between #2020-01-01# and #2020-12-31#\r\n\r\n/*\r\ndelete from sub \r\nwhere docno in (\r\n    select docno from main where docdate between #2020-01-01# and #2020-12-31#\r\n)\r\n\r\ndelete from main where docdate between #2020-01-01# and #2020-12-31#\r\n*/', 4, 1, NULL, NULL, '2025-10-23 01:15:20'),
	(96, 'เช็ครหัสสินค้า ผูก รหัสบัญชี', 'WW/Product information management/Common/Released products\r\n\r\nPosting', 3, 1, '1761182191_68f981ef01615_22-10-2025 16-44-34.png', NULL, '2025-10-23 01:16:31'),
	(97, 'เช็ค Settenment Mark ค้าง ทำรายการไม่สมบูรณ์ ว่าติดอยู่ในรายการไหน', '"This transaction has been marked for settlement by another user" ส่วนใหญ่หมายความว่าธุรกรรมนี้ (เช่น Invoice) ถูกเลือก (Mark) ไว้ในหน้า Settlement ที่อื่น ซึ่งอาจจะเป็น:\r\n/*\r\nSELECT b.* \r\nfrom SPECTRANS a \r\nLEFT JOIN LEDGERJOURNALTRANS b ON b.RECID = a.SPECRECID\r\nWHERE b.ECL_PAYEENAME LIKE \'%เจ้าหนี้อื่น%\'\r\nORDER BY a.CREATEDDATETIME  desc\r\n*/', 3, 1, '1761211413_68f9f415ce79a_23-10-2025 16-22-23.png', NULL, '2025-10-23 09:23:33'),
	(98, 'Query ดึงข้อมูล Product Recipt RPO', 'SELECT j.PURCHID,v.INTERNALPACKINGSLIPID\r\nFROM VENDPACKINGSLIPJOUR j\r\nright JOIN VENDPACKINGSLIPVERSION v\r\n   ON j.recid = v.VENDPACKINGSLIPJOUR\r\nWHERE j.PURCHID = \'OCPO2508024\'', 3, 1, NULL, NULL, '2025-11-03 08:27:57'),
	(99, 'ปัญหาไม่สามารถ Invoice PO CN ได้', '- เนื่องจากไม่ได้ผู้รหัสบัญชี\r\n- ผู้รหัสบัญชีหลักจาก เพิ่มข้อมูล รายการสินค้าแล้ว', 3, 1, '1762251361_6909d261bf3ec_4-11-2025 16-58-16.png', NULL, '2025-11-04 10:16:01'),
	(100, 'ลงทะเบียนนายม้าข้อมูลไม่ครบ', 'ติดปัญหา : ไม่สามารถ Recal ค่าแรงนายม้ายได้ เกิด error ข้อผิดพลาด สามารถดู error เพิ่มเติมได้จาก Log', 5, 1, '1762307308_690aacec0a137_เช็คการลงทะเบียนนายม้า.png', '1762307308_690aacec0a73b_3128463.jpg', '2025-11-05 01:48:28'),
	(101, 'build App QR-code-old', 'git pull origin qrcode_2025\r\ngrails war woodwork_barcode_2.war', 1, 1, NULL, NULL, '2025-11-06 09:27:22'),
	(102, 'Query Show กระบวนการส่งออก', 'select \r\n	wet.sale_order_no ,wet.is_active ,wet.is_completed ,wet.is_interfaced ,wet.container_no \r\n	,wsl.sale_line_id,wit.is_active ,wit.humidity ,bb.is_active ,bb.barcode_no\r\nfrom public.wood_export_exporttransaction wet\r\nleft join public.wood_export_exportsaleline wsl \r\n	on wsl.transaction_id = wet.id\r\nleft join public.wood_export_exportitem wit \r\n	on wit.export_sale_line_id = wsl.id\r\nleft join public.barcode_barcode bb \r\n	on bb.id = wit.barcode_id \r\nwhere wet.sale_order_no = \'Ulsod2511006\' \r\n	and wet.container_no = \'1\'', 6, 1, NULL, NULL, '2025-11-07 02:54:14'),
	(103, 'นำเข้าข้อมูล โดยใช้วิธี Excel Add-in', '1. เลือกบริษัท และ เลือก Port -> Live ,TEST\r\n2. ค้นหา Table ที่จะนำเข้าข้อมูล\r\n3. เลือก ฟิวด์ ที่จะนำเข้าข้อมูล\r\n4. กด รีเฟรส เพื่อดึงข้อมูลในระบบที่มี มาแสดง เป็นตัวอย่าง\r\n5. กด ฟิวด์ เพื่อล้างข้อมูล ให้เหลือแต่ หัว คอร์ดลัม แล้วนำข้อมูล ที่จะนำเข้า ไปวาง\r\n6. เผยแพร่', 3, 1, '1762576742_690ec966f0637_excel-add-in.png', '1762576742_690ec966f0cba_NumberSequence_WGH420.csv', '2025-11-08 04:39:02'),
	(104, 'รายงานภาษี หัก ณ ที่จ่าย', 'WW/General ledger/Area page/Eclipse Thai Localization/Withholding tax/Report/Withholding tax slip', 3, 1, '1763083872_69168660d4d2f_รายงานภาษีหัก ณ ที่จ่าย.png', NULL, '2025-11-14 01:31:12'),
	(105, 'ไม่สามารถ Post รายการจ่ายเงินได้', 'Transactions have been seled for settlent, although Settlemert type none was sected for vendor PLF-3745-00, voucher WG-BAP25115.5\r\npath: WW/Accounts payable/Area page/Journals/Payments/Payment journal\r\n\r\nขั้นตอนที่เกิด :: Post Journal จ่ายเงิน\r\nวิธีแก้ไข :: เอา Mark รายการนั้นออกก่อน แล้ว ลอง Post รายการดูใหม่\r\nสาเหตุ :: ระบบทำรายการ settlement ไม่สมบูรณ์ ให้ยกเลิก แล้ว ทำรายการ Post รายการจ่ายเงินดูใหม่ครับ', 3, 1, '1763610771_691e909338612_messageImage_1763605560246.jpg', NULL, '2025-11-20 03:52:51'),
	(106, 'Trigger บันทึก Log แก้ไขเกจ์ไม้ รายการ ตรวจรับไม้ท่อน', 'DELIMITER $$\r\n\r\nCREATE TRIGGER TG_EDIT_PALET\r\nAFTER UPDATE ON log_woodqc\r\nFOR EACH ROW\r\nBEGIN\r\n    IF OLD.guage_number <> NEW.guage_number THEN\r\n        INSERT INTO user_action_history (\r\n            action,\r\n            time,\r\n            user_id,\r\n            barcode_id\r\n        ) VALUES (\r\n            CONCAT(\'EDIT_PALET OLD: \', OLD.guage_number, \' NEW: \', NEW.guage_number),\r\n            NOW(),\r\n            NEW.qc_user_id,\r\n            NULL\r\n        );\r\n    END IF;\r\nEND$$\r\n\r\nDELIMITER ;', 5, 1, NULL, NULL, '2025-11-20 10:03:25'),
	(107, 'Query แก้ไข สลับบัตรชั่ง ซื้อคืน ระบบตาชั่งเล็ก', 'update wood_return b\r\nLEFT JOIN (\r\n	SELECT \r\n		a.truck_transaction_id,a.ticket2,a.out_date_time,a.cust_code,a.cust_name,a.license_plate,a.item_name,a.net_weight,a.wherehouse \r\n		,a.wherehouse_name,a.location,a.wood_type,a.truck_type,a.truck_type_name,a.item_ax,a.batch_id \r\n	FROM truck_trans a WHERE ticket2 = \'0000464687\'\r\n) tt ON 1 = 1\r\nSET b.ticket_id = tt.ticket2\r\n	,b.ticket_date = tt.out_date_time\r\n	,b.cust_code = tt.cust_code\r\n	,b.cust_name = tt.cust_name\r\n	,b.license_plate = tt.license_plate\r\n	,b.prod_type_id = tt.item_name\r\n	,b.wood_weight = tt.net_weight\r\n	,b.wherehouse = tt.wherehouse\r\n	,b.wherehouse_name = tt.wherehouse_name\r\n	,b.location = tt.location\r\n	,b.wood_type = tt.wood_type\r\n	,b.truck_type = tt.truck_type\r\n	,b.truck_type_name = tt.truck_type_name\r\n	,b.item_ax = tt.item_ax\r\n	,b.batch_id = tt.batch_id\r\n	,b.truck_transaction_id = tt.truck_transaction_id\r\n	\r\nWHERE 1=1 \r\n	and b.ticket_id = \'6000464790\' \r\n	AND b.return_type = 0', 8, 1, NULL, NULL, '2025-12-11 02:51:17'),
	(108, 'Query Update  คำนวณน้ำหนัก ,ราคาสุทธิ รายการประเมินไม้ท่อน', 'SET @ticket2 := \'6000013452\';\r\n\r\nUPDATE truck_transaction tt\r\ninner JOIN log_wood_evaluate_data evl\r\n	ON evl.truck_transaction_id = tt.id\r\ninner JOIN (\r\n	SELECT ticket2,in_weight,out_weight\r\n		,in_weight-out_weight AS bef_weight\r\n		,cut_weight_amount\r\n		,(in_weight-out_weight)-cut_weight_amount AS net_weight\r\n		,buy_price\r\n		,((in_weight-out_weight)-cut_weight_amount)*buy_price AS buy_amount\r\n	FROM (\r\n		SELECT a.ticket2,a.id,a.in_weight,a.out_weight\r\n			,a.in_weight-a.out_weight AS be_weight\r\n			,SUM(IFNULL(d.weight,0)) AS cut_weight_amount\r\n			,b.buy_price\r\n		FROM truck_transaction a \r\n		LEFT JOIN log_wood_evaluate_data b ON b.truck_transaction_id = a.id\r\n		LEFT JOIN log_wood_evaluate_data_cut_weight_evaluate c ON c.log_wood_evaluate_data_eval_cut_weight_list_id = b.id\r\n		LEFT JOIN cut_weight_evaluate d ON d.id = c.cut_weight_evaluate_id\r\n		WHERE a.ticket2 = @ticket2\r\n		GROUP BY a.ticket2\r\n	)a\r\n)b\r\n	ON b.ticket2 = tt.ticket2\r\nSET \r\n	tt.net_weight = b.net_weight\r\n	,evl.cut_weight = b.cut_weight_amount\r\n	,evl.buy_amount = b.buy_amount\r\nWHERE tt.ticket2 = @ticket2\r\n\r\nSELECT * FROM cut_weight_evaluate;\r\n\r\nSELECT b.*\r\nFROM truck_transaction a \r\nLEFT JOIN log_wood_evaluate_data b ON b.truck_transaction_id = a.id\r\nWHERE a.ticket2 = \'c\';\r\n\r\nSELECT * FROM log_wood_evaluate_data_cut_weight_evaluate;\r\n\r\nSELECT * FROM choice_domain WHERE class = \'com.ww.log.CutWeightChoice\';', 5, 1, NULL, NULL, '2025-12-13 03:37:19'),
	(109, 'Query Outpay', 'SELECT\r\n	dbo.tEmployee.EmployeeCode AS code\r\n	,dbo.tEmployee.EnglishName AS name_en\r\n	,dbo.tEmployee.FirstName + \' \' + dbo.tEmployee.LastName AS name\r\n	,dbo.tEmployeeTitle.EmployeeTitle AS title\r\n	,dbo.tEmployeeTitle.EmployeeTitle_EN AS title_en\r\n	,dbo.tEmployeeStatus.EMPStatus AS status\r\n	,dbo.tEmployeeStatus.EMPSTG_ID, dbo.tSiteTR.Site_Name\r\n	,aa.*\r\nFROM dbo.tEmployee\r\nINNER JOIN dbo.tEmployeeTitle ON dbo.tEmployee.EMPTT_ID = dbo.tEmployeeTitle.EMPTT_ID\r\nINNER JOIN dbo.tEmployeeStatus ON dbo.tEmployee.EMPST_ID = dbo.tEmployeeStatus.EMPST_ID\r\nINNER JOIN dbo.tSiteTR ON dbo.tEmployee.Site_ID = dbo.tSiteTR.Site_ID\r\nINNER JOIN (\r\n	SELECT employeecode,p09,cwu ,createdatetime \r\n	FROM tPayroll \r\n	WHERE 1=1 \r\n		-- and employeecode = \'2023-00339\' \r\n		AND tax91_typecalTax = \'สิ้นปี\'\r\n)aa on dbo.tEmployee.EmployeeCode = aa.employeecode\r\nWHERE 1=1 \r\n	-- AND (dbo.tEmployee.EmployeeCode = \'2023-00339\')\r\n	AND dbo.tSiteTR.Site_Name = \'WU\'\r\n	AND dbo.tEmployeeStatus.EMPSTG_ID = \'AC\'\r\n	AND dbo.tEmployeeTitle.EmployeeTitle LIKE \'%ข้อมูล%\'\r\n	--and dbo.tEmployee.FirstName LIKE \'%กนกวรร%\'\r\nORDER BY dbo.tEmployee.EmployeeCode,aa.createdatetime\r\n	-- GROUP BY dbo.tEmployee.EmployeeCode', 4, 1, NULL, NULL, '2025-12-29 09:59:14'),
	(110, 'สถานะใบขอสั่งซื้อไม่เปลี่ยนให้ ตามการทำรายการ', 'ปัญหา : กด Approved PR มาแล้ว แต่สถานะยังเป็น In review อยู่ ทำให้ไม่สามารถดึง PR มาเปิด PO ได้\r\n\r\nแก้ไข : เช็ค Batch Job WorkFlow ให้สถานะเป็น Waiting ตรวจสอบข้อมูลตามภาพ', 3, 1, '1767684671_695cba3f6ebd5_BatchJobWorkFlowไม่ทำงาน.png', NULL, '2026-01-06 07:31:11'),
	(111, 'ระบบ AX ค้าง', 'ระบบ AX บน Terminal ค้าง มีแจ้งเตือน ตอนรีโมทเข้าไปใน Terminal ปัญหาไฟล์ cash ในเครื่องหลัก\r\nวีธีแก้ไข : เครื่องหลัก run -> %localappdata%\\Microsoft\\Terminal Server Client\\Cache -> ลบไฟล์ Cash ทิ้ง', 3, 1, '1769821522_697d55522ca1d_30-1-2026 16-17-46.png', NULL, '2026-01-31 01:05:22'),
	(112, 'test', 'test', 1, 1, 'img_1769852635_301.png', 'doc_1769852635_579.pdf', '2026-01-31 09:43:55'),
	(113, 'Access Query', 'SELECT * from main a\r\nleft join sub b on b.docno = a.docno\r\nwhere a.docdate = #2026-01-30# and a.doccode between \'11\' and \'16\'', 4, 1, '', '', '2026-02-05 09:46:10'),
	(114, 'รหัสผ่านเข้าคอมสาขา', '', 9, 1, 'img_1770341664_821.jpg', '', '2026-02-06 01:34:24'),
	(115, 'ปัญหารับเข้า - เบิกออก ไม่ได้', 'Fiscal period for 6/2/2026 is not open', 3, 1, 'img_1770369432_283.png', '', '2026-02-06 09:17:12'),
	(116, 'วิธีการค้นหา เปลี่ยนเล่ม รหัสเอกสาร AX', '1. ขายปีกไม้ -> Number sequence code = *TS \r\n- ทั้งหมด 3 รายการ\r\n2. ใบยกเลิก-ใบสั่งขาย Return -> Number sequence code = *TRT\r\n- ทั้งหมด 3 รายการ', 3, 1, '', '', '2026-02-10 04:49:25'),
	(117, 'Terminal ax สาขาที่ใช้งาน', 'Terminal ax\r\n18 : WC WU WP WT\r\n23 : WQ WB WN WO WA โรงไฟฟ้า', 3, 1, '', '', '2026-02-11 04:12:45'),
	(118, 'เพิ่มสิทธิการใช้งานตรวจสอบ ชั่วคราว รอแก้ไขสิทธิใช้งาน', 'SELECT ur.*\r\nFROM \r\n-- update \r\nuser u\r\nleft join employee em on u.username = em.code\r\nleft join user_role ur on ur.user_id = u.id\r\nleft join role r on r.id = ur.role_id\r\n-- SET ur.rale_id = 3\r\nwhere ifnull(u.username,\'\') IN (\'2022-01185\',\'2020-00737\',\'2026-00158\')\r\n    and u.enabled = 1\r\n\r\n\r\nINSERT INTO user_role (role_id ,user_id)\r\nSELECT 21,id FROM user WHERE username = \'2022-01185\';\r\n\r\nINSERT INTO user_role (role_id ,user_id)\r\nSELECT 21,id FROM user WHERE username = \'2020-00737\';\r\n\r\nINSERT INTO user_role (role_id ,user_id)\r\nSELECT 21,id FROM user WHERE username = \'2026-00158\';\r\n\r\n', 4, 1, '', '', '2026-02-25 06:49:15'),
	(119, 'Query เคลียร์ข้อมูลนับไม้ ระบบค่าแรง4', 'select * from sub \r\nwhere docno in (\r\n	SELECT docno from main where docdate between #2020-01-01# and #2020-12-31#\r\n)\r\n\r\nSELECT * from main where docdate between #2020-01-01# and #2020-12-31#\r\n\r\n/*\r\ndelete from sub \r\nwhere docno in (\r\n    select docno from main where docdate between #2020-01-01# and #2020-12-31#\r\n)\r\n\r\ndelete from main where docdate between #2020-01-01# and #2020-12-31#\r\n*/', 4, 1, '', '', '2026-02-26 03:55:54'),
	(120, 'ดึงข้อมูลเวลา outpay', 'SELECT	 employeecode,datestamp,InTime_Hour,InTime_Minute,OutTime2_Hour,OutTime2_Minute,OutTime_Hour,OutTime_Minute\r\nFROM tTimeInOut WHERE employeecode IN (\'2023-00339\')\r\nAND datestamp >= \'20260202\'', 4, 1, '', '', '2026-02-26 07:16:42'),
	(121, 'ปรับสถานะ interface SM ไม้เลื่อย', '\r\n// update ค่า 2 ตาราง\r\nselect *\r\nfrom log_woodqc\r\nwhere DATE(scale_date_time) between \'2026-02-27\' AND \'2026-02-28\'\r\n\r\nupdate log_woodqc\r\nset is_interfacedsm =0\r\nwhere DATE(scale_date_time) between \'2026-02-27\' AND \'2026-02-28\'\r\n\r\n\r\n\r\n//ตารางที่2\r\nselect w.*\r\nfrom wood_size_amount_map w\r\ninner join mobile_raw_wood_data_wood_size_amount_map s on s.wood_size_amount_map_id = w.id\r\ninner join mobile_raw_wood_data d on d.id = s.mobile_raw_wood_data_amount_map_id\r\ninner join raw_wood_source r on r.id = d.raw_wood_source_id\r\ninner join barcode b on b.id = r.barcode_id\r\nwhere r.produce_date between \'2026-02-27\' AND \'2026-02-28\'\r\n\r\n\r\nupdate wood_size_amount_map w\r\ninner join mobile_raw_wood_data_wood_size_amount_map s on s.wood_size_amount_map_id = w.id\r\ninner join mobile_raw_wood_data d on d.id = s.mobile_raw_wood_data_amount_map_id\r\ninner join raw_wood_source r on r.id = d.raw_wood_source_id\r\ninner join barcode b on b.id = r.barcode_id\r\nset w.is_interfacedsm =0\r\nwhere r.produce_date between \'2026-02-27\' AND \'2026-02-28\'\r\n', 5, 1, '', '', '2026-03-02 06:00:44'),
	(122, 'ค้นหาข้อมูล Vendor ช้าเป็น User เดียว', 'ปัญหา : ค้นหารหัส Vendor เจ้าหนี้ แล้วค้าง เป็น User เดียว\r\nวิธีแก้ไข : \r\n- ให้ทุกเครื่อง ที่ใช้ User นี้ ปิดโปรแกรม AX ทั้งหมด ให้เช็ค User Online\r\n- เข้าระบบ User ที่เจอปัญหา Reset Usage Data \r\n- ปิดโปรแกรม แล้วเปิดใหม่', 3, 1, 'img_1772616804_991.png', '', '2026-03-04 09:33:24'),
	(123, 'เคลียร์ Usage Data User อื่น ด้วยสิทธิ Admin', '', 3, 1, 'img_1772672891_770.png', '', '2026-03-05 01:08:11'),
	(124, 'การบันทึกตั้งหนี้ค่าใช้จ่าย', '', 3, 1, 'img_1773137517_985.png', '', '2026-03-10 10:11:57'),
	(125, 'สร้าง Trigger Update ข้อมูล รหัสลูกค้า รายการชั่งไม้ท่อน', '-- ให้ Update ข้อมูลไปยังรายการ ชั่งไม้ท่อน ซื้อคืน ,ส่งคืน\r\n\r\nDELIMITER $$\r\nCREATE TRIGGER update_truck_company_wood_return\r\nBEFORE UPDATE ON truck_transaction\r\nFOR EACH ROW\r\nBEGIN\r\n    DECLARE count_rt        DECIMAL(10,2);\r\n    DECLARE truck_comp_code VARCHAR(100);\r\n    DECLARE truck_comp_name VARCHAR(100);\r\n\r\n    IF NEW.truck_company_id <> OLD.truck_company_id THEN\r\n\r\n        SELECT COUNT(*)\r\n        INTO   count_rt\r\n        FROM   scaledata.wood_return\r\n        WHERE  ticket_id = NEW.ticket2; -- เช็คว่า มีรายการชั่งไม้ท่อน ซื้อคืน ส่งคืนไหม \r\n\r\n        SELECT code, name\r\n        INTO   truck_comp_code, truck_comp_name\r\n        FROM   truck_company\r\n        WHERE  id = NEW.truck_company_id\r\n        LIMIT 1; -- ดึงข้อมูล รหัสเจ้าหนี้ และ ชื่อเจ้าหนี้\r\n\r\n        IF count_rt > 0 THEN -- ถ้ามีข้อมูล รายการชั่งไม้ท่อน ซื้อคืน ,ส่งคืน\r\n            UPDATE scaledata.wood_return\r\n            SET    cust_code = truck_comp_code\r\n                  ,cust_name = truck_comp_name\r\n            WHERE  ticket_id = NEW.ticket2; -- อัพเดต ข้อมูล\r\n        END IF;\r\n\r\n    END IF;\r\nEND$$\r\nDELIMITER ;', 5, 1, '', '', '2026-03-11 08:47:08');
